    internal List<Virial.Game.Player?> ExtraVotes { get; private init; } = new();

    internal MeetingTieVoteHostEvent(Dictionary<byte, Virial.Game.Player?> voteForMap)
    {
        this.voteForMap = voteForMap;
    }

