    /// <summary>
    /// 他の規則を無視してキルできない相手に設定します。
    /// </summary>
    public void SetAsCannotKillForcedly() => cannotKillForcedly = true;

    public PlayerCheckCanKillLocalEvent(Virial.Game.Player player, Virial.Game.Player target) : base(player)
    {
        this.Target = target;
    }
}

