public class PlayerTasksTrySetLocalEvent : AbstractPlayerEvent
{
    public class Task { 
        internal NetworkedPlayerInfo.TaskInfo MyTask { get; private init; }
        uint Id => MyTask.Id;
        byte TaskTypeId => MyTask.TypeId;

        internal Task(NetworkedPlayerInfo.TaskInfo task)
        {
